import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../contextos/AuthContext';
import { crearReserva } from '../data/mockStorage';
import { obtenerTripulacionViaje } from '../data/mockStaffDB';
import TicketGenerator from '../componentes/TicketGenerator';
import TripulacionInfo from '../componentes/TripulacionInfo';
import '../estilos/escritorio/mapa-asientos.css';

/**
 * MapaAsientos — V3: Full reservation flow with seat selection,
 * passenger form, ticket generation (PDF+QR), and WhatsApp share.
 */
const MapaAsientos = () => {
    const { viajeId } = useParams();
    const navigate = useNavigate();
    const { sesion, login } = useAuth();

    // Seat state
    const [cargando, setCargando] = useState(true);
    const [asientosReservados] = useState(['1A', '2B', '5C']); // Hardcoded mock occupied seats
    const [asientosSeleccionados, setAsientosSeleccionados] = useState([]);

    // Flow state: 'mapa' → 'formulario' → 'ticket'
    const [paso, setPaso] = useState('mapa');

    // Passenger form
    const [pasajeroNombre, setPasajeroNombre] = useState('');
    const [pasajeroCI, setPasajeroCI] = useState('');
    const [pasajeroTelefono, setPasajeroTelefono] = useState('');

    // Auth modal (for unauthenticated users)
    const [mostrarAuthModal, setMostrarAuthModal] = useState(false);
    const [authEmail, setAuthEmail] = useState('');
    const [authPass, setAuthPass] = useState('');
    const [authLoading, setAuthLoading] = useState(false);
    const [authError, setAuthError] = useState('');

    // Generated reservation
    const [reservaGenerada, setReservaGenerada] = useState(null);

    // Crew info
    const [tripulacion, setTripulacion] = useState(null);

    useEffect(() => {
        setTimeout(() => setCargando(false), 500);
        // Load crew info for this trip
        const crew = obtenerTripulacionViaje(viajeId);
        setTripulacion(crew);
    }, [viajeId]);

    const toggleAsiento = (id) => {
        if (asientosReservados.includes(id)) return;
        setAsientosSeleccionados(prev =>
            prev.includes(id) ? prev.filter(a => a !== id) : [...prev, id]
        );
    };

    // Step 1 → Step 2: check auth before moving to passenger form
    const handleContinuar = () => {
        if (asientosSeleccionados.length === 0) {
            alert('Seleccione al menos un asiento.');
            return;
        }
        if (!sesion) {
            setMostrarAuthModal(true);
        } else {
            setPaso('formulario');
        }
    };

    // Auth submit
    const handleAuthSubmit = async (e) => {
        e.preventDefault();
        setAuthLoading(true);
        setAuthError('');
        try {
            const result = await login(authEmail, authPass);
            if (result.exito) {
                setMostrarAuthModal(false);
                setPaso('formulario');
            } else {
                setAuthError(result.error || 'Credenciales inválidas.');
            }
        } catch (err) {
            setAuthError(err.message || 'Error de conexión.');
        }
        setAuthLoading(false);
    };

    // Step 2 → Step 3: create reservation and show ticket
    const handleConfirmarReserva = (e) => {
        e.preventDefault();
        if (!pasajeroNombre || !pasajeroCI) {
            alert('Complete todos los campos obligatorios.');
            return;
        }

        const nuevaReserva = crearReserva({
            viajeId,
            pasajeroNombre,
            pasajeroCI,
            pasajeroTelefono,
            asientos: asientosSeleccionados,
            busPlaca: 'ABC-1234',
            origen: 'La Paz',
            destino: 'Cochabamba',
            precio: asientosSeleccionados.length * 45,
            fechaSalida: '2026-04-02T08:00:00',
        });

        setReservaGenerada(nuevaReserva);
        setPaso('ticket');
    };

    // Render bus layout
    const filas = Array.from({ length: 10 }, (_, i) => i + 1);
    const columnas = ['A', 'B', 'pasillo', 'C', 'D'];

    return (
        <div style={{ backgroundColor: '#0f172a', minHeight: '100vh', color: '#f1f5f9', padding: '1.5rem' }}>
            <div style={{ maxWidth: '850px', margin: '0 auto' }}>

                {/* Navigation */}
                <button
                    onClick={() => navigate(-1)}
                    style={{
                        background: 'transparent', border: '1px solid #475569', color: '#cbd5e1',
                        padding: '0.5rem 1rem', borderRadius: '8px', cursor: 'pointer', marginBottom: '1rem'
                    }}
                >
                    ← Volver
                </button>

                {/* Progress indicator */}
                <div style={{ display: 'flex', gap: '0.5rem', marginBottom: '1.5rem' }}>
                    {['Asientos', 'Datos', 'Ticket'].map((label, i) => {
                        const pasos = ['mapa', 'formulario', 'ticket'];
                        const activo = pasos.indexOf(paso) >= i;
                        return (
                            <div key={label} style={{
                                flex: 1, padding: '0.5rem', textAlign: 'center', borderRadius: '6px',
                                background: activo ? '#3b82f6' : '#1e293b',
                                color: activo ? 'white' : '#64748b',
                                fontSize: '0.8rem', fontWeight: activo ? 600 : 400, transition: 'all 0.3s'
                            }}>
                                {i + 1}. {label}
                            </div>
                        );
                    })}
                </div>

                {cargando ? (
                    <p style={{ textAlign: 'center', color: '#60a5fa' }}>Cargando distribución del bus...</p>
                ) : (
                    <>
                        {/* ═══════ PASO 1: MAPA DE ASIENTOS ═══════ */}
                        {paso === 'mapa' && (
                            <div>
                                {/* Crew & Bus Info Panel */}
                                {tripulacion && (
                                    <TripulacionInfo
                                        conductor={tripulacion.conductor}
                                        ayudante={tripulacion.ayudante}
                                        bus={tripulacion.bus}
                                    />
                                )}
                            <div style={{ display: 'flex', gap: '2rem', flexWrap: 'wrap', justifyContent: 'center' }}>
                                <div className="bus-cuerpo">
                                    <div className="bus-frente">
                                        <span className="bus-volante">🔘 Volante</span>
                                        <span className="bus-puerta-etiqueta">Puerta 🚪</span>
                                    </div>
                                    <div className="bus-piso">
                                        {filas.map(fila => (
                                            <div key={fila} style={{ display: 'flex', gap: '0.4rem', marginBottom: '0.4rem' }}>
                                                <div style={{ width: '1.8rem', textAlign: 'center', color: '#64748b', fontSize: '0.7rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{fila}</div>
                                                {columnas.map(col => {
                                                    if (col === 'pasillo') {
                                                        return <div key="p" style={{ width: '24px' }} className="bus-pasillo-visual" />;
                                                    }
                                                    const id = `${fila}${col}`;
                                                    const reservado = asientosReservados.includes(id);
                                                    const seleccionado = asientosSeleccionados.includes(id);
                                                    let cls = 'disponible';
                                                    if (reservado) cls = 'ocupado';
                                                    if (seleccionado) cls = 'pendiente';
                                                    return (
                                                        <button key={col} className={`asiento-btn ${cls}`}
                                                            style={{ width: '38px', height: '38px', fontSize: '0.7rem', cursor: reservado ? 'not-allowed' : 'pointer', fontWeight: 'bold' }}
                                                            onClick={() => toggleAsiento(id)}
                                                        >
                                                            {id}
                                                        </button>
                                                    );
                                                })}
                                            </div>
                                        ))}
                                        <div className="bus-zona-bano">🚻 Baño</div>
                                    </div>
                                </div>

                                {/* Side panel */}
                                <div style={{ background: '#1e293b', padding: '1.5rem', borderRadius: '12px', border: '1px solid #334155', minWidth: '280px', flex: 1 }}>
                                    <h3 style={{ marginTop: 0, color: '#f1f5f9' }}>Resumen</h3>
                                    <div style={{ color: '#94a3b8', marginBottom: '0.5rem', fontSize: '0.9rem' }}>
                                        Viaje: La Paz → Cochabamba
                                    </div>
                                    <div style={{ color: '#94a3b8', fontSize: '0.85rem', marginBottom: '1rem' }}>
                                        Asientos: {asientosSeleccionados.length > 0 ? asientosSeleccionados.join(', ') : 'Ninguno'}
                                    </div>

                                    {/* Leyenda */}
                                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem', marginBottom: '1.5rem', fontSize: '0.8rem' }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                                            <div style={{ width: 14, height: 14, borderRadius: 3, background: '#334155', border: '1px solid #475569' }} /> Libre
                                        </div>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                                            <div style={{ width: 14, height: 14, borderRadius: 3, background: '#b45309', border: '1px solid #d97706' }} /> Tuyo
                                        </div>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                                            <div style={{ width: 14, height: 14, borderRadius: 3, background: '#7f1d1d', border: '1px solid #991b1b' }} /> Ocupado
                                        </div>
                                    </div>

                                    <div style={{ borderTop: '1px solid #334155', paddingTop: '1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                                        <span style={{ color: '#94a3b8' }}>Total:</span>
                                        <span style={{ fontWeight: 'bold', fontSize: '1.3rem', color: '#10b981' }}>Bs {asientosSeleccionados.length * 45}</span>
                                    </div>

                                    <button onClick={handleContinuar}
                                        disabled={asientosSeleccionados.length === 0}
                                        style={{
                                            width: '100%', padding: '0.9rem', border: 'none', borderRadius: '10px',
                                            background: asientosSeleccionados.length > 0 ? '#3b82f6' : '#475569',
                                            color: 'white', fontWeight: 600, cursor: asientosSeleccionados.length > 0 ? 'pointer' : 'not-allowed',
                                            fontSize: '0.95rem'
                                        }}
                                    >
                                        Continuar →
                                    </button>
                                </div>
                            </div>
                            </div>
                        )}

                        {/* ═══════ PASO 2: FORMULARIO PASAJERO ═══════ */}
                        {paso === 'formulario' && (
                            <div style={{ maxWidth: '500px', margin: '0 auto' }}>
                                <h2 style={{ marginBottom: '0.5rem' }}>Datos del Pasajero</h2>
                                <p style={{ color: '#94a3b8', marginBottom: '1.5rem', fontSize: '0.9rem' }}>
                                    Asiento(s): <span style={{ color: '#60a5fa', fontWeight: 600 }}>{asientosSeleccionados.join(', ')}</span>
                                </p>

                                <form onSubmit={handleConfirmarReserva} style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
                                    <div>
                                        <label style={{ display: 'block', color: '#94a3b8', fontSize: '0.85rem', marginBottom: '0.4rem' }}>
                                            Nombre Completo <span style={{ color: '#ef4444' }}>*</span>
                                        </label>
                                        <input type="text" value={pasajeroNombre} onChange={e => setPasajeroNombre(e.target.value)} required
                                            placeholder="Ej. Juan Pérez"
                                            style={{ width: '100%', boxSizing: 'border-box', background: '#0f172a', border: '1px solid #334155', color: '#f1f5f9', padding: '0.8rem', borderRadius: '8px', fontSize: '0.95rem' }}
                                        />
                                    </div>
                                    <div>
                                        <label style={{ display: 'block', color: '#94a3b8', fontSize: '0.85rem', marginBottom: '0.4rem' }}>
                                            Carnet de Identidad (CI) <span style={{ color: '#ef4444' }}>*</span>
                                        </label>
                                        <input type="text" value={pasajeroCI} onChange={e => setPasajeroCI(e.target.value)} required
                                            placeholder="Ej. 1234567"
                                            style={{ width: '100%', boxSizing: 'border-box', background: '#0f172a', border: '1px solid #334155', color: '#f1f5f9', padding: '0.8rem', borderRadius: '8px', fontSize: '0.95rem' }}
                                        />
                                    </div>
                                    <div>
                                        <label style={{ display: 'block', color: '#94a3b8', fontSize: '0.85rem', marginBottom: '0.4rem' }}>
                                            Teléfono (para WhatsApp)
                                        </label>
                                        <input type="tel" value={pasajeroTelefono} onChange={e => setPasajeroTelefono(e.target.value)}
                                            placeholder="Ej. 59177012345"
                                            style={{ width: '100%', boxSizing: 'border-box', background: '#0f172a', border: '1px solid #334155', color: '#f1f5f9', padding: '0.8rem', borderRadius: '8px', fontSize: '0.95rem' }}
                                        />
                                        <span style={{ fontSize: '0.75rem', color: '#64748b' }}>Opcional. Se usará para enviar tu pasaje por WhatsApp.</span>
                                    </div>

                                    <div style={{ display: 'flex', gap: '1rem', marginTop: '0.5rem' }}>
                                        <button type="button" onClick={() => setPaso('mapa')}
                                            style={{ flex: 1, padding: '0.8rem', background: 'transparent', border: '1px solid #475569', color: '#94a3b8', borderRadius: '10px', cursor: 'pointer' }}
                                        >
                                            ← Volver
                                        </button>
                                        <button type="submit"
                                            style={{ flex: 2, padding: '0.8rem', background: '#10b981', color: 'white', border: 'none', borderRadius: '10px', fontWeight: 600, cursor: 'pointer', fontSize: '0.95rem' }}
                                        >
                                            Confirmar Reserva ✓
                                        </button>
                                    </div>
                                </form>
                            </div>
                        )}

                        {/* ═══════ PASO 3: TICKET GENERADO ═══════ */}
                        {paso === 'ticket' && reservaGenerada && (
                            <TicketGenerator
                                reserva={reservaGenerada}
                                onCerrar={() => navigate('/')}
                            />
                        )}
                    </>
                )}
            </div>

            {/* ═══════ AUTH MODAL (for unauthenticated users) ═══════ */}
            {mostrarAuthModal && (
                <div style={{
                    position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
                    background: 'rgba(15,23,42,0.85)', backdropFilter: 'blur(4px)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    zIndex: 60, padding: '1rem'
                }}>
                    <div style={{
                        background: '#1e293b', width: '100%', maxWidth: '400px', borderRadius: '12px',
                        padding: '2rem', border: '1px solid #334155', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.5)'
                    }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
                            <h2 style={{ margin: 0, color: '#f1f5f9', fontSize: '1.2rem' }}>Inicia sesión para continuar</h2>
                            <button onClick={() => setMostrarAuthModal(false)} style={{ background: 'transparent', border: 'none', color: '#94a3b8', fontSize: '1.5rem', cursor: 'pointer' }}>×</button>
                        </div>
                        <p style={{ color: '#94a3b8', fontSize: '0.85rem', marginBottom: '1.5rem' }}>
                            Necesitas una cuenta para reservar. Prueba: admin@tbb.com / admin123456
                        </p>
                        <form onSubmit={handleAuthSubmit}>
                            {authError && <div style={{ background: 'rgba(239,68,68,0.1)', color: '#ef4444', padding: '0.75rem', borderRadius: '6px', fontSize: '0.85rem', marginBottom: '1rem' }}>{authError}</div>}
                            <div style={{ marginBottom: '1rem' }}>
                                <label style={{ display: 'block', fontSize: '0.85rem', color: '#94a3b8', marginBottom: '0.4rem' }}>Email</label>
                                <input type="email" value={authEmail} onChange={e => setAuthEmail(e.target.value)} required
                                    style={{ width: '100%', boxSizing: 'border-box', background: '#0f172a', border: '1px solid #334155', color: '#f1f5f9', padding: '0.8rem', borderRadius: '8px' }} />
                            </div>
                            <div style={{ marginBottom: '1.5rem' }}>
                                <label style={{ display: 'block', fontSize: '0.85rem', color: '#94a3b8', marginBottom: '0.4rem' }}>Contraseña</label>
                                <input type="password" value={authPass} onChange={e => setAuthPass(e.target.value)} required
                                    style={{ width: '100%', boxSizing: 'border-box', background: '#0f172a', border: '1px solid #334155', color: '#f1f5f9', padding: '0.8rem', borderRadius: '8px' }} />
                            </div>
                            <button type="submit" disabled={authLoading}
                                style={{ width: '100%', padding: '0.8rem', borderRadius: '8px', border: 'none', background: '#3b82f6', color: 'white', fontWeight: 600, cursor: authLoading ? 'wait' : 'pointer' }}>
                                {authLoading ? 'Verificando...' : 'Ingresar'}
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default MapaAsientos;
